questionvariables.text:
/* exd: shortest exact decimal display of a terminating value (up to 3 d.p.) */
exd(v) := if integerp(v) then v else if integerp(10*v) then dispdp(float(v),1) else if integerp(100*v) then dispdp(float(v),2) else dispdp(float(v),3);
/* Design: describe a region with inequalities. Entries [r, rel1, rel2]; relation 1 <, 2 <=, 3 >, 4 >= (each relation at least twice per input). rel1 <= 2: inside the circle; rel2 <= 2: A's side (PA < PB); even index: boundary solid (included). Keep the disc about A clear of x = 0: a disc of radius 2 touches x = 0, which can reduce the region to a single point or make PA < PB redundant. Source: original. */
q71: [[5/2,1,1],[5/2,2,3],[3,4,2],[7/2,3,4],[3,2,4],[5/2,1,2],[3,3,1],[7/2,4,3],[3,2,1],[5/2,4,4]];
ix: 1+rand(10);
r: q71[ix][1]; rl1: q71[ix][2]; rl2: q71[ix][3];
rk: ["rlt","rle","rgt","rge"];
ta1: rk[rl1]; ta2: rk[rl2];
/* same direction, other strictness */
sd1: rk[[2,1,4,3][rl1]]; sd2: rk[[2,1,4,3][rl2]];
/* opposite direction, same strictness */
op1: rk[[3,4,1,2][rl1]]; op2: rk[[3,4,1,2][rl2]];
ins: if is(rl1<=2) then 1 else 0;
asd: if is(rl2<=2) then 1 else 0;
solc: if evenp(rl1) then 1 else 0;
soll: if evenp(rl2) then 1 else 0;
mko(c) := [["rlt",is(c="rlt"),"<"],["rle",is(c="rle"),"≤"],["rgt",is(c="rgt"),">"],["rge",is(c="rge"),"≥"]];
o1: mko(ta1); o2: mko(ta2);
arl: sconcat("Points A and B are 4 cm apart on a centimetre grid. A circle with centre A, radius ", if integerp(r) then string(r) else string(float(r)), " cm, is drawn ",
  if is(solc=1) then "solid" else "dashed", ". The perpendicular bisector of AB is drawn ", if is(soll=1) then "solid" else "dashed",
  ". Everything is shaded grey except the required region, which is left clear: it is ", if is(ins=1) then "inside" else "outside", " the circle and on ", if is(asd=1) then "A's" else "B's", " side of the bisector.");
